class TokenBucket:
    def __init__(self, rate, capacity):
        self.rate = rate
        self.capacity = capacity
        self._buckets = {}

    def allow(self, key):
        now = time.monotonic()
        if key not in self._buckets:
            self._buckets[key] = {'tokens': self.capacity, 'last_update': now}

        bucket = self._buckets[key]
        elapsed = now - bucket['last_update']
        bucket['tokens'] = min(self.capacity, bucket['tokens'] + elapsed * self.rate)
        bucket['last_update'] = now

        if bucket['tokens'] >= 1:
            bucket['tokens'] -= 1
            return True, 0
        else:
            retry_after = (1 - bucket['tokens']) / self.rate
            return False, retry_after

# Rate limiter: 5 requests/minuto (5/60 = 0.083 tokens/segundo)
login_limiter = TokenBucket(rate=0.083, capacity=5)

def login(username, password, client_ip):
    allowed, retry_after = login_limiter.allow(client_ip)
    if not allowed:
        return {'status': 'rate_limited', 'code': 429, 'retry_after': retry_after}

    if verificar_credenciales(username, password):
        return {'status': 'ok', 'token': 'abc123'}
    else:
        return {'status': 'error', 'message': 'Invalid credentials'}

